  if (masked) {
    items.push({ status: "warn", name: `已脱敏 ${masked} 行`, detail: "提交前须人工确认占位符未破坏代码可读性，审计日志不保存原始秘密。" });
  }
  if (excluded.length) {
    items.push({ status: "pass", name: `排除 ${excluded.length} 个生成文件`, detail: "生成标记文件未计入有效源码。" });
  }
